#!/usr/bin/env python3
"""Print the next order id."""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_encode(n: int) -> str:
    """Encode an integer as a base-36 string."""
    if n == 0:
        return "0"
    chars = []
    while n > 0:
        chars.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(chars))


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    n = 0
    for c in s.upper():
        n = n * 36 + BASE36.index(c)
    return n


def next_id(current: str) -> str:
    """Given ORD-XXXX, return the next ORD-XXXX."""
    suffix = current.split("-", 1)[1]
    n = base36_decode(suffix) + 1
    encoded = base36_encode(n)
    # Pad or truncate to 4 characters
    encoded = encoded[-4:].zfill(4)
    return f"ORD-{encoded.upper()}"


def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last = lines[-1]
    print(next_id(last))


if __name__ == "__main__":
    main()

