#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import sys

def next_id(last_id: str) -> str:
    """Given an id like ORD-243G, return the next one."""
    prefix, suffix = last_id.rsplit("-", 1)
    # Treat suffix as a base-36 number and increment.
    chars = list(suffix)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if "0" <= c <= "8":
            chars[i] = chr(ord(c) + 1)
            return f"{prefix}-{''.join(chars)}"
        elif c == "9":
            chars[i] = "A"
            return f"{prefix}-{''.join(chars)}"
        elif "A" <= c <= "Y":
            chars[i] = chr(ord(c) + 1)
            return f"{prefix}-{''.join(chars)}"
        elif c == "Z":
            chars[i] = "0"
            # Carry continues to the next position
        else:
            sys.exit(f"Invalid character in id: {c!r}")
    # If we fell through, all characters rolled over (e.g., ZZZZ -> 0000 with carry)
    # We keep the same width and just return 0000 with a warning.
    return f"{prefix}-{''.join(chars)}"

def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        sys.exit("ids.txt not found")
    if not lines:
        sys.exit("ids.txt is empty")
    last = lines[-1]
    print(next_id(last))

if __name__ == "__main__":
    main()

