import re

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def to_base36(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base-36 string of given width."""
    digits = []
    for _ in range(width):
        digits.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    n = 0
    for c in s:
        n = n * 36 + BASE36.index(c)
    return n


def main() -> None:
    last_id = None
    with open('ids.txt') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            m = re.search(r'ORD-([0-9A-Z]+)', line)
            if m:
                last_id = m.group(1)

    if last_id is None:
        raise SystemExit('error: no valid id found in ids.txt')

    next_val = from_base36(last_id) + 1
    next_id = to_base36(next_val)
    print(f'ORD-{next_id}')


if __name__ == '__main__':
    main()

