import sys

def increment_base36(s: str) -> str:
    """Increment a base-36 encoded string by 1."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if '0' <= c <= '8':
            chars[i] = chr(ord(c) + 1)
            return ''.join(chars)
        elif c == '9':
            chars[i] = 'A'
            return ''.join(chars)
        elif 'A' <= c <= 'Y':
            chars[i] = chr(ord(c) + 1)
            return ''.join(chars)
        elif c == 'Z':
            chars[i] = '0'
            continue
    # If we overflowed (e.g. ZZZZ), prepend '1'
    return '1' + ''.join(chars)

def main():
    with open('ids.txt', 'r') as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        next_id = 'ORD-0000'
    else:
        last_id = lines[-1]
        suffix = last_id.split('-')[1]
        next_suffix = increment_base36(suffix)
        next_id = f'ORD-{next_suffix}'

    print(next_id)

