"""Print the next order id.

Reads ids.txt from the current directory (one order id per line,
most recent last) and prints the next sequential id to stdout.
Ids have the form "ORD-" followed by four characters, where the
four-character suffix is a fixed-width base-36 counter (0-9, A-Z).
"""

from pathlib import Path

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def increment(suffix: str) -> str:
    """Return suffix + 1 as a fixed-width base-36 string."""
    chars = list(suffix)
    for i in range(len(chars) - 1, -1, -1):
        idx = BASE36.index(chars[i])
        if idx < len(BASE36) - 1:
            chars[i] = BASE36[idx + 1]
            return "".join(chars)
        chars[i] = BASE36[0]
    raise ValueError(f"overflow: no id after {suffix!r}")


def next_id(last_id: str) -> str:
    prefix, suffix = last_id.rsplit("-", 1)
    return f"{prefix}-{increment(suffix)}"


def main() -> None:
    lines = [
        line.strip()
        for line in Path("ids.txt").read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    if not lines:
        raise SystemExit("ids.txt is empty; cannot compute the next id")
    print(next_id(lines[-1]))


if __name__ == "__main__":
    main()

