#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import sys

BASE36_DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int, width: int = 4) -> str:
    """Convert integer to zero-padded base36 string of given width."""
    digits = []
    for _ in range(width):
        digits.append(BASE36_DIGITS[n % 36])
        n //= 36
    return "".join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert base36 string to integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36_DIGITS.index(ch)
    return n


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    # Expected format: ORD-XXXX
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"Error: unexpected id format: {last_id!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    num = from_base36(suffix)
    next_num = num + 1
    next_suffix = to_base36(next_num, width=4)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

