#!/usr/bin/env python3
"""Print the next order id.

Reads ids.txt from the current directory (one order id per line, most recent
last) and prints the next sequential id to stdout followed by a newline. Ids
have the form ORD- followed by four characters; the suffix is a base36 number
that is incremented (zero-padded to four characters).
"""

import sys

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_int(suffix):
    n = 0
    for ch in suffix:
        n = n * 36 + ALPHABET.index(ch)
    return n


def to_suffix(n):
    if n == 0:
        return "0" * 4
    digits = []
    while n:
        n, rem = divmod(n, 36)
        digits.append(ALPHABET[rem])
    return "".join(reversed(digits)).rjust(4, "0")


def next_id(last_id):
    return "ORD-" + to_suffix(to_int(last_id[len("ORD-"):]) + 1)


def main():
    line = None
    with open("ids.txt", encoding="utf-8") as handle:
        for raw in handle:
            stripped = raw.strip()
            if stripped:
                line = stripped
    if line is None:
        sys.exit("ids.txt contains no ids")
    print(next_id(line))


if __name__ == "__main__":
    main()
