"""Print the next order id to stdout.

Reads ids.txt (current directory, one id per line, most recent last)
and prints ORD- followed by the next 4-character base-36 id.
"""

import pathlib


def to_base36(n: int, width: int = 4) -> str:
    """Encode *n* as a *width*-character zero-padded base-36 string."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(width):
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result))


def next_id(ids_path: pathlib.Path) -> str:
    lines = ids_path.read_text().strip().splitlines()
    if not lines:
        return "ORD-" + to_base36(0)
    last = lines[-1].strip()
    suffix = last.removeprefix("ORD-")
    n = int(suffix, 36)
    return "ORD-" + to_base36(n + 1)


if __name__ == "__main__":
    print(next_id(pathlib.Path("ids.txt")))

