import sys


def to_base36(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base36 string."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    if not result:
        result.append("0")
    result.reverse()
    return "".join(result).zfill(width)


def from_base36(s: str) -> int:
    """Parse a base36 string to an integer."""
    return int(s, 36)


def main():
    try:
        with open("ids.txt", encoding="utf-8") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    if not last_id.startswith("ORD-"):
        print("ORD-0000")
        return

    suffix = last_id[4:]
    try:
        n = from_base36(suffix)
    except ValueError:
        print("ORD-0000")
        return

    n += 1
    # If the incremented value exceeds 4-character base36 max (36^4 - 1),
    # widen the width to accommodate
    width = max(4, len(to_base36(n, width=4)))
    print(f"ORD-{to_base36(n, width=width)}")


if __name__ == "__main__":
    main()

