"""Read ids.txt and print the next sequential order id to stdout.

Order ids have the form ORD-XXXX where XXXX is a base-36 encoded
value.  ids.txt lists one order id per line, most recent last.
"""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(val: int, width: int) -> str:
    """Encode *val* as a *width*-character zero-padded base-36 string."""
    chars = []
    for _ in range(width):
        chars.append(BASE36[val % 36])
        val //= 36
    return "".join(reversed(chars))


def next_id(last_id: str) -> str:
    """Given ``ORD-XXXX`` return the following id in sequence."""
    prefix = last_id[:4]   # "ORD-"
    suffix = last_id[4:]   # the four base-36 chars
    return prefix + to_base36(int(suffix, 36) + 1, 4)


def main() -> None:
    try:
        with open("ids.txt") as fh:
            lines = fh.readlines()
    except FileNotFoundError:
        print("Error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    last_id: str | None = None
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        # Lines look like "1\tORD-243G" – find the token starting with ORD-
        for token in line.split():
            if token.startswith("ORD-"):
                last_id = token

    if last_id is None:
        print("Error: no order id found in ids.txt", file=sys.stderr)
        sys.exit(1)

    print(next_id(last_id))


if __name__ == "__main__":
    main()

