#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events sharing an event_id, write deduped.jsonl."""

import json

def main():
    seen = set()
    with open("events.jsonl", "r") as fin, open("deduped.jsonl", "w") as fout:
        for line in fin:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid in seen:
                continue
            seen.add(eid)
            fout.write(line + "\n")

if __name__ == "__main__":
    main()

