#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate event_ids (keep first), write deduped.jsonl."""

import json

SEEN_KEY = "event_id"

seen = set()
with open("events.jsonl", "r") as inf, open("deduped.jsonl", "w") as outf:
    for line in inf:
        line = line.strip()
        if not line:
            continue
        record = json.loads(line)
        eid = record.get(SEEN_KEY)
        if eid is None:
            # Lines without event_id are always written.
            pass
        elif eid in seen:
            continue
        else:
            seen.add(eid)
        outf.write(json.dumps(record, separators=(",", ":")) + "\n")

