#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events sharing an event_id (keep first),
and write the unique events to deduped.jsonl."""

import json


def dedupe_events(input_path="events.jsonl", output_path="deduped.jsonl"):
    seen = set()
    unique = []

    with open(input_path, "r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid not in seen:
                seen.add(eid)
                unique.append(event)

    with open(output_path, "w") as f:
        for event in unique:
            f.write(json.dumps(event) + "\n")

    print(f"Read from {input_path}, wrote {len(unique)} unique events to {output_path}")


if __name__ == "__main__":
    dedupe_events()

