#!/usr/bin/env python3
import json


def dedupe_events(input_path='events.jsonl', output_path='deduped.jsonl'):
    seen = set()
    with open(input_path, encoding='utf-8') as f_in, \
         open(output_path, 'w', encoding='utf-8') as f_out:
        for line in f_in:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get('event_id')
            if eid not in seen:
                seen.add(eid)
                f_out.write(json.dumps(event) + '\n')


if __name__ == '__main__':
    dedupe_events()

