#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 hashes for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(file_path: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} is not a directory")
        return

    manifest = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel_path = str(path.relative_to(RELEASE_DIR.parent))
            manifest[rel_path] = sha256_digest(path)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Written {MANIFEST_PATH} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

