"""Print the file names under reports/, one per line, in report order."""

import os
import re


def natural_sort_key(filename):
    """Split filename into components for natural (human-friendly) sorting."""
    return [int(text) if text.isdigit() else text.lower()
            for text in re.split(r'(\d+)', filename)]


def main():
    reports_dir = "reports"
    try:
        files = os.listdir(reports_dir)
    except FileNotFoundError:
        print(f"Error: directory '{reports_dir}' not found.")
        return
    except NotADirectoryError:
        print(f"Error: '{reports_dir}' is not a directory.")
        return

    # Filter to only files (skip subdirectories)
    files = [f for f in files
             if os.path.isfile(os.path.join(reports_dir, f))]

    files.sort(key=natural_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

