args.new_string:
"""Rotate entries from app.log to archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message. Entries
strictly older than 7 days before AS_OF are moved to archive.log (appended,
preserving order). The remaining entries stay in app.log in their original order.
"""

import sys
from datetime import datetime, timezone

SECONDS_IN_7_DAYS = 7 * 24 * 60 * 60


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer, got {sys.argv[1]}", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - SECONDS_IN_7_DAYS
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    # Read all entries from app.log
    try:
        with open("app.log") as f:
