#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - 7 * 86400  # strictly older than 7 days before AS_OF

    app_path = "app.log"
    archive_path = "archive.log"

    try:
        with open(app_path) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    keep = []
    archive = []

    for line in lines:
        line = line.rstrip("\n")
        if not line:
            continue
        # Parse the leading timestamp: YYYY-MM-DD HH:MM:SS
        ts_str = line[:19]
        try:
            dt = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
            entry_ts = int(dt.timestamp())
        except ValueError:
            # If timestamp can't be parsed, keep the line in app.log
            keep.append(line)
            continue

        if entry_ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Append old entries to archive.log
    if archive:
        with open(archive_path, "a") as f:
            for line in archive:
                f.write(line + "\n")

    # Rewrite app.log with remaining entries
    with open(app_path, "w") as f:
        for line in keep:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

