"""Rotate old entries from app.log to archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line in app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS. Entries whose timestamp is
strictly older than 7 days before AS_OF are moved to archive.log (appended,
preserving order). The remaining entries are written back to app.log in
their original order.
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse a leading YYYY-MM-DD HH:MM:SS timestamp from the line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp, got {sys.argv[1]!r}", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff_dt = as_of_dt - timedelta(days=7)

    log_path = "app.log"
    archive_path = "archive.log"

    try:
        with open(log_path, "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {log_path} not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        # Preserve empty lines and unparseable lines in app.log
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    # Strip trailing newlines for consistent output (no trailing blank line)
    keep_stripped = [l.rstrip("\n") for l in keep]
    archive_stripped = [l.rstrip("\n") for l in archive]

    # Remove trailing empty lines
    while keep_stripped and keep_stripped[-1] == "":
        keep_stripped.pop()
    while archive_stripped and archive_stripped[-1] == "":
        archive_stripped.pop()

    # Write back app.log (remaining entries)
    if keep_stripped:
        with open(log_path, "w") as f:
            for line in keep_stripped:
                f.write(line + "\n")
    else:
        # Empty file, write nothing
        open(log_path, "w").close()

    # Append to archive.log
    if archive_stripped:
        with open(archive_path, "a") as f:
            for line in archive_stripped:
                f.write(line + "\n")

    print(f"Rotated {len(archive_stripped)} entries to {archive_path}, "
          f"{len(keep_stripped)} entries remain in {log_path}")


if __name__ == "__main__":
    main()

