"""Rotate entries in app.log older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_line_timestamp(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' prefix from line and return naive datetime."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    with open("app.log", encoding="utf-8") as f:
        lines = f.readlines()

    kept = []
    archived = []

    for line in lines:
        ts = parse_line_timestamp(line)
        if ts is not None:
            # Compare naive datetime (assumed UTC) against cutoff (UTC-aware)
            line_dt = ts.replace(tzinfo=timezone.utc)
            if line_dt < cutoff:
                archived.append(line)
            else:
                kept.append(line)
        else:
            # Lines that don't start with a valid timestamp stay in app.log
            kept.append(line)

    with open("archive.log", "a", encoding="utf-8") as f:
        for entry in archived:
            f.write(entry if entry.endswith("\n") else entry + "\n")

    with open("app.log", "w", encoding="utf-8") as f:
        for entry in kept:
            f.write(entry if entry.endswith("\n") else entry + "\n")


if __name__ == "__main__":
    main()

