#!/usr/bin/env python3
"""Rotate old entries from app.log into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message. Entries
whose timestamp is strictly older than 7 days before AS_OF are moved to
archive.log (appended, preserving order). The remaining entries stay in
app.log in their original order.
"""

import datetime
import os
import sys


def parse_line_timestamp(line: str) -> datetime.datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None


def line_to_unix_ts(line: str) -> int | None:
    """Convert the leading timestamp of a log line to Unix seconds (UTC)."""
    dt = parse_line_timestamp(line)
    if dt is None:
        return None
    return int(dt.replace(tzinfo=datetime.timezone.utc).timestamp())


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer (got {sys.argv[1]!r})", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 24 * 60 * 60  # 604800 seconds

    app_log_path = os.path.join(os.path.dirname(__file__) or ".", "app.log")
    archive_log_path = os.path.join(os.path.dirname(__file__) or ".", "archive.log")

    # Read all lines from app.log
    try:
        with open(app_log_path, "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    kept: list[str] = []
    rotated: list[str] = []

    for line in lines:
        ts = line_to_unix_ts(line)
        if ts is not None and ts < cutoff:
            rotated.append(line)
        else:
            kept.append(line)

    # Append rotated entries to archive.log
    if rotated:
        with open(archive_log_path, "a") as f:
            f.writelines(rotated)

    # Rewrite app.log with kept entries
    with open(app_log_path, "w") as f:
        f.writelines(kept)


if __name__ == "__main__":
    main()

